  AUDIOCPP_ERR_INVALID_ARGUMENT(1),
  AUDIOCPP_ERR_UNSUPPORTED_FAMILY(2),
  AUDIOCPP_ERR_LOAD_FAILED(3),
  AUDIOCPP_ERR_RUNTIME(4),
  AUDIOCPP_ERR_OUT_OF_MEMORY(5),
  AUDIOCPP_ERR_OUT_OF_RANGE(6),
  AUDIOCPP_ERR_NOT_AVAILABLE(7);

  final int value;
  const audiocpp_status(this.value);

  static audiocpp_status fromValue(int value) => switch (value) {
    0 => AUDIOCPP_OK,
    1 => AUDIOCPP_ERR_INVALID_ARGUMENT,
    2 => AUDIOCPP_ERR_UNSUPPORTED_FAMILY,
    3 => AUDIOCPP_ERR_LOAD_FAILED,
    4 => AUDIOCPP_ERR_RUNTIME,
    5 => AUDIOCPP_ERR_OUT_OF_MEMORY,
    6 => AUDIOCPP_ERR_OUT_OF_RANGE,
    7 => AUDIOCPP_ERR_NOT_AVAILABLE,
    _ => throw ArgumentError('Unknown value for audiocpp_status: $value'),
  };
}

